                all(grid[r0][x] == color and grid[r1][x] == color for x in range(c0,c1+1)) and
                all(grid[y][c0] == color and grid[y][c1] == color for y in range(r0,r1+1))):
                frames.append((color,r0,r1,c0,c1))

    if not frames:
        return out

    # Pick the frame containing the richest interior pattern.
    src = max(frames, key=lambda f: sum(
        grid[y][x] != 0
        for y in range(f[1]+1, f[2])
        for x in range(f[3]+1, f[4])
    ))
    sr, er, sc, ec = src[1]+1, src[2], src[3]+1, src[4]
    pattern = [[grid[y][x] != 0 for x in range(sc, ec)] for y in range(sr, er)]

    for color, r0, r1, c0, c1 in frames:
        if (color,r0,r1,c0,c1) == src:
            continue
        ih, iw = r1-r0-1, c1-c0-1
        for y in range(ih):
            for x in range(iw):
                # Repeat/clip the pattern to cover each frame's interior.
                out[r0+1+y][c0+1+x] = color if pattern[y % len(pattern)][x % len(pattern[0])] else 0
    return out
